public static void alternating(int N) {
    StringBuilder result = new StringBuilder();
    for (int i = 0; i <= 2 * N; i++) {
        if (i % 2 == 0) {
            result.append("1");
        } else {
            result.append("0");
        }
    }
    System.out.print(result.toString());
}
